            | "onpointermove"
            | "onpointerup"
            | "onpointercancel"
            | "onpointerenter"
            | "onpointerleave"
            | "onpointerover"
            | "onpointerout"
            | "onmousedown"
            | "onmousemove"
            | "onmouseup"
            | "onmouseenter"
            | "onmouseleave"
            | "onmouseover"
            | "onmouseout"
            | "ontouchstart"
