        assert_eq!(preconnect.crossorigin.as_deref(), Some(""));

        let font = &summary.resources[1];
        assert_eq!(font.kind, "preload");
        assert_eq!(font.as_hint.as_deref(), Some("font"));
        assert_eq!(font.type_hint.as_deref(), Some("font/woff2"));
