        assert_eq!(font.integrity.as_deref(), Some("sha384-font"));
        assert_eq!(font.crossorigin.as_deref(), Some("anonymous"));
        assert_eq!(font.fetchpriority.as_deref(), Some("high"));

        let module = &summary.resources[2];
